BEGIN;
ON CONFLICT(code) DO NOTHING;
UPDATE platform.commercial_plans SET limits=jsonb_set(limits,'{permissions,permissoes}',
 (SELECT jsonb_agg(code) FROM iam.capabilities WHERE parent_code IS NOT NULL AND status='ACTIVE' AND code<>'workspace.tracking.open'))
 WHERE code='BASICO' AND status='DRAFT' AND version=1;
COMMIT;
